async def act(page):
    """
    1) Attempt to use the site-aware helper create_curated_collection_by_search(...) to perform
       the search for 'Collector' (this helper navigates to '/' and returns scraped results).
    2) If the helper returns results, attempt to click the first search result shown in
       role='main' -> first role='article' -> first role='link'. Return the helper's result as-is.
    3) If the helper raises or does not produce usable results (for example because an overlay
       blocks the complementary region), fall back to a manual search flow:
       - navigate to '/'
       - dismiss obvious dialog overlays if present
       - locate the visible search input (preferred inside a complementary region)
       - enter 'Collector' and activate the search (prefer clicking a Search button, else press Enter)
       - wait for role='main' and click the first result link
    Notes:
    - All locator indexing is guarded by .count() checks to avoid indexing errors.
    - The click that is expected to navigate away is performed as the last DOM action.
    """
    results = None

    # 1) Try the knowledge-base helper first (required when available).
    try:
        results = await create_curated_collection_by_search(page, "Collector")
    except Exception:
        results = None

    # Helper may have executed and left the results on the page. If so, try to click
    # the first result (main -> article[0] -> link[0]). This click should be the last action.
    async def click_first_result_from_main():
        main = page.get_by_role("main")
        try:
            # allow a brief moment for client-side rendering if needed
            await main.wait_for(state="visible", timeout=3000)
        except Exception:
            pass

        articles = main.get_by_role("article")
        try:
            article_count = await articles.count()
        except Exception:
            article_count = 0

        if article_count > 0:
            first_article = articles.nth(0)
            links = first_article.get_by_role("link")
            try:
                link_count = await links.count()
            except Exception:
                link_count = 0

            if link_count > 0:
                # Click the first link inside the first article (last action)
                await links.nth(0).click()
                return True

            # If no explicit link, try clicking the article itself
            try:
                await first_article.click()
                return True
            except Exception:
                return False

        # Fallback: try first link directly under main
        main_links = main.get_by_role("link")
        try:
            main_link_count = await main_links.count()
        except Exception:
            main_link_count = 0

        if main_link_count > 0:
            await main_links.nth(0).click()
            return True

        return False

    # If helper returned data, attempt to click the first result shown on the page.
    if results is not None:
        try:
            clicked = await click_first_result_from_main()
            # Return the helper API response unchanged as required.
            return results
        except Exception:
            # If clicking failed for some reason, fall through to fallback manual flow.
            pass

    # 2) Fallback manual flow: navigate to root and try to perform the visible search ourselves.
    try:
        await page.goto('/')
    except Exception:
        # If navigation fails, continue and attempt to operate on current page state
        pass

    # Dismiss a dialog/overlay if present (the search helper does NOT dismiss overlays).
    try:
        dialog_count = await page.get_by_role("dialog").count()
    except Exception:
        dialog_count = 0

    if dialog_count > 0:
        dialog = page.get_by_role("dialog").nth(0)
        close_names = ["Close", "close", "Dismiss", "×", "x", "OK", "Got it"]
        dismissed = False
        for name in close_names:
            try:
                btns = dialog.get_by_role("button", name=name)
                if await btns.count() > 0:
                    try:
                        await btns.nth(0).click()
                        dismissed = True
                        break
                    except Exception:
                        # try next candidate
                        dismissed = False
            except Exception:
                # try next candidate label
                continue

        if not dismissed:
            # As a last resort try the first button inside the dialog
            try:
                btns_all = dialog.get_by_role("button")
                if await btns_all.count() > 0:
                    await btns_all.nth(0).click()
            except Exception:
                pass
    else:
        # No dialog role present; try to click any obvious close button on the page
        close_labels = ["Close", "close", "Dismiss", "×", "x", "OK", "Got it"]
        for lbl in close_labels:
            try:
                btns = page.get_by_role("button", name=lbl)
                if await btns.count() > 0:
                    try:
                        await btns.nth(0).click()
                        break
                    except Exception:
                        continue
            except Exception:
                continue

    # Locate search input: prefer inside complementary region
    search_input = None
    try:
        comp_count = await page.get_by_role("complementary").count()
    except Exception:
        comp_count = 0

    if comp_count > 0:
        comp = page.get_by_role("complementary").nth(0)
        # Try searchbox then textbox inside complementary region
        try:
            if await comp.get_by_role("searchbox").count() > 0:
                search_input = comp.get_by_role("searchbox").nth(0)
            elif await comp.get_by_role("textbox").count() > 0:
                search_input = comp.get_by_role("textbox").nth(0)
        except Exception:
            search_input = None
    else:
        # No complementary region: try to find a search input anywhere
        try:
            if await page.get_by_role("searchbox").count() > 0:
                search_input = page.get_by_role("searchbox").nth(0)
            elif await page.get_by_role("textbox").count() > 0:
                search_input = page.get_by_role("textbox").nth(0)
        except Exception:
            search_input = None

    if search_input is None:
        # Could not find a search input; return an empty list to indicate no API result
        return []

    # Fill the input with our query
    try:
        await search_input.fill("Collector")
    except Exception:
        try:
            # fallback to type if fill not available
            await search_input.type("Collector")
        except Exception:
            pass

    # Try to activate search: prefer a Search button inside the complementary region
    activated = False
    try:
        if comp_count > 0:
            comp = page.get_by_role("complementary").nth(0)
            try:
                # preferred: button whose name includes 'search'
                search_button = comp.get_by_role("button", name="search")
                if await search_button.count() > 0:
                    await search_button.nth(0).click()
                    activated = True
                else:
                    # fallback: first button inside complementary
                    all_buttons = comp.get_by_role("button")
                    if await all_buttons.count() > 0:
                        await all_buttons.nth(0).click()
                        activated = True
            except Exception:
                activated = False
        else:
            # Try a global Search button
            try:
                global_search = page.get_by_role("button", name="search")
                if await global_search.count() > 0:
                    await global_search.nth(0).click()
                    activated = True
            except Exception:
                activated = False
    except Exception:
        activated = False

    if not activated:
        # Press Enter in the input as last resort
        try:
            await search_input.press("Enter")
        except Exception:
            pass

    # Wait for results to appear inside role='main'
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # Attempt to click the first result now
    try:
        await click_first_result_from_main()
    except Exception:
        pass

    # Fallback return when helper wasn't usable: return an empty list (no API response to pass through)
    return []

